"""
Internal helpers for running independent symbolic computations in threads.

Threads only help on CPython builds without the global interpreter lock
(free-threaded builds).  On a GIL build, or when only one CPU is available to
the process, :func:`pmap` is exactly the sequential list comprehension it
replaces, so results, exceptions and side-effect order are unchanged.
"""

import os
import sys
import threading
from concurrent.futures import ThreadPoolExecutor

__all__ = ['pmap']

_executor = None
_executor_lock = threading.Lock()
_worker_state = threading.local()


def _gil_enabled():
    check = getattr(sys, '_is_gil_enabled', None)
    return True if check is None else check()


def _available_cpus():
    try:
        return len(os.sched_getaffinity(0))
    except (AttributeError, OSError):  # pragma: no cover - platform specific
        return os.cpu_count() or 1


_nworkers = None


def _threads_usable():
    global _nworkers
    if _nworkers is None:
        _nworkers = _available_cpus()
    return _nworkers > 1 and not _gil_enabled()


def _get_executor():
    global _executor
    if _executor is None:
        with _executor_lock:
            if _executor is None:
                _executor = ThreadPoolExecutor(
                    max_workers=_nworkers,
                    thread_name_prefix='sympy-pmap',
                    initializer=_mark_worker)
    return _executor


def _mark_worker():
    _worker_state.active = True


def _in_worker():
    return getattr(_worker_state, 'active', False)


def pmap(func, items):
    """
    Return ``[func(x) for x in items]``, evaluating the calls concurrently
    when the interpreter runs free-threaded and more than one CPU is
    available.

    Results are returned in input order.  If several calls raise, the
    exception of the earliest item is re-raised, as the sequential
    comprehension would do.  Calls made from inside a worker run
    sequentially so that nested use cannot deadlock the pool.
    """
    items = list(items)
    if len(items) < 2 or _in_worker() or not _threads_usable():
        return [func(x) for x in items]

    executor = _get_executor()
    futures = [executor.submit(func, x) for x in items]
    results = []
    error = None
    for fut in futures:
        try:
            results.append(fut.result())
        except BaseException as exc:
            if error is None:
                error = exc
            results.append(None)
    if error is not None:
        raise error
    return results

